#!/bin/bash

helm uninstall external-secrets --namespace external-secrets
kubectl delete ns external-secrets

#!/bin/bash

# Delete all k8s resources of this app
kubectl delete -f https://raw.githubusercontent.com/civo/kubernetes-marketplace/master/permission-manager/app.yaml

#!/bin/bash

helm uninstall argo-cd --namespace argocd
kubectl delete ns argocd

#!/bin/bash

#Remove Ketch NS
kubectl delete namespace ketch-system

#!/bin/bash

# Delete the custom CRDs
kubectl delete -f app.yaml

#!/bin/bash

# Delete the app
kubectl delete -f cert-manager.yaml
